import java.util.Arrays;
import java.util.stream.Collectors;

class PigLatinTranslator {

    private static final String VOWELS = "aeiou";

    public String translate(String phrase) {
        if (phrase == null) {
            return null;
        }
        return Arrays.stream(phrase.trim().split("\\s+"))
                .map(this::translateWord)
                .collect(Collectors.joining(" "));
    }

    private String translateWord(String word) {
        int length = word.length();
        if (length == 0) {
            return word;
        }

        // Rule 1: starts with a vowel, or with "xr" or "yt".
        if (isVowel(word.charAt(0)) || word.startsWith("xr") || word.startsWith("yt")) {
            return word + "ay";
        }

        // Find the consonant cluster at the start of the word.
        int split = 0;
        while (split < length && !isVowel(word.charAt(split))) {
            // Rule 4: consonants followed by 'y' -> move consonants before 'y'.
            if (word.charAt(split) == 'y') {
                break;
            }
            // Rule 3: zero or more consonants followed by "qu" -> move consonants and "qu".
            if (word.charAt(split) == 'q'
                    && split + 1 < length
                    && word.charAt(split + 1) == 'u') {
                split += 2;
                break;
            }
            split++;
        }

        // Rules 2, 3 and 4: move the prefix to the end and add "ay".
        return word.substring(split) + word.substring(0, split) + "ay";
    }

    private static boolean isVowel(char c) {
        return VOWELS.indexOf(c) >= 0;
    }
}
